package com.fran.tv;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.text.*;
import java.util.*;

public class MainActivity extends Activity {
 Ui u;FrameLayout root;LinearLayout home,nav,grid;TextView status,section;EditText search;ScrollView gridScroll;
 List<Channel> channels=new ArrayList<>(),visible=new ArrayList<>();String category="Todos",query="",lastFocus="";
 Handler handler=new Handler(Looper.getMainLooper());boolean intro=true,enteringPlayer=false,refreshing=false;Updater updater;
 @Override public void onCreate(Bundle b){super.onCreate(b);u=new Ui(this);u.immersive();updater=new Updater(this,u);channels=Catalog.load(this);category=Catalog.prefs(this).getString("category","Puerto Rico");buildHome();welcome();refresh(false);}
 @Override protected void onRestart(){super.onRestart();if(!enteringPlayer&&!updater.externalFlow){welcome();refresh(false);}enteringPlayer=false;}
 @Override protected void onResume(){super.onResume();u.immersive();if(home!=null&&!intro){renderGrid(true);updater.resume();}}
 void buildHome(){
  root=new FrameLayout(this);root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff071523,0xff020812}));setContentView(root);
  home=u.row();home.setGravity(Gravity.TOP);home.setPadding(u.d(24),u.d(20),u.d(24),u.d(14));root.addView(home,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout sidebar=u.column();sidebar.setPadding(0,0,u.d(18),0);home.addView(sidebar,u.lp(202,-1));
  LinearLayout brand=u.row();brand.addView(u.brand(42));TextView word=u.text("FranTV",27,Ui.WHITE,true);brand.addView(word);sidebar.addView(brand,u.lp(-1,48));u.gap(sidebar,15);
  ScrollView ns=new ScrollView(this);ns.setClipToPadding(true);ns.setClipChildren(true);ns.setVerticalScrollBarEnabled(false);nav=u.column();nav.setPadding(u.d(3),u.d(3),u.d(4),u.d(6));ns.addView(nav);sidebar.addView(ns,new LinearLayout.LayoutParams(-1,0,1));renderNav();
  u.gap(sidebar,8);TextView refresh=u.button("↻  Actualizar canales",()->refresh(true));sidebar.addView(refresh,u.lp(-1,34));u.gap(sidebar,5);
  TextView updates=u.button("↑  Buscar actualización",()->updater.check(true));sidebar.addView(updates,u.lp(-1,34));
  TextView version=u.text("FranTV  ·  "+BuildConfig.VERSION_NAME,10,Ui.MUTED,false);version.setPadding(u.d(12),u.d(10),0,0);sidebar.addView(version);
  LinearLayout body=u.column();home.addView(body,new LinearLayout.LayoutParams(0,-1,1));
  FrameLayout hero=new FrameLayout(this);ImageView scenic=new ImageView(this);scenic.setImageResource(R.drawable.hero);scenic.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(scenic,new FrameLayout.LayoutParams(-1,-1));
  View shade=new View(this);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xef051321,0x10051321}));hero.addView(shade,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout copy=u.column();copy.setPadding(u.d(20),u.d(14),u.d(18),0);copy.addView(u.text("TU TELEVISIÓN, TU FORMA DE DISFRUTAR",10,Ui.MUTED,false));u.gap(copy,9);copy.addView(u.text("Tu isla. Tus canales.",30,Ui.WHITE,true));u.gap(copy,6);copy.addView(u.text("Elige un canal y disfruta.",13,0xffc5d4e1,false));hero.addView(copy,new FrameLayout.LayoutParams(-1,-1));hero.setClipToOutline(true);hero.setBackground(u.bg(Ui.CARD,14,0));body.addView(hero,u.lp(-1,124));
  LinearLayout heading=u.row();heading.setPadding(u.d(3),u.d(12),u.d(3),u.d(8));section=u.text("Canales",20,Ui.WHITE,true);heading.addView(section,new LinearLayout.LayoutParams(0,-2,1));TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setTextColor(Ui.MUTED);clock.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,u.d(12));heading.addView(clock);body.addView(heading,u.lp(-1,44));
  search=new EditText(this);search.setSingleLine(true);search.setHint("Nombre o número del canal");search.setTextColor(Ui.WHITE);search.setHintTextColor(Ui.MUTED);search.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,u.d(15));search.setPadding(u.d(12),0,u.d(12),0);search.setBackground(u.bg(Ui.CARD,10,Ui.CYAN));search.setVisibility(View.GONE);body.addView(search,u.lp(-1,38));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString().trim();renderGrid(false);}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((t,action,event)->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);if(grid.getChildCount()>0)grid.focusSearch(View.FOCUS_DOWN);focusFirst();return true;});
  gridScroll=new ScrollView(this);gridScroll.setVerticalScrollBarEnabled(false);gridScroll.setClipToPadding(false);gridScroll.setClipChildren(false);grid=u.column();grid.setPadding(u.d(5),u.d(5),u.d(5),u.d(6));gridScroll.addView(grid);body.addView(gridScroll,new LinearLayout.LayoutParams(-1,0,1));
  status=u.text("",10,Ui.MUTED,false);status.setPadding(u.d(4),u.d(6),0,u.d(4));body.addView(status);
  body.addView(u.text("↑↓←→  Navegar     OK  Ver canal     Mantén OK  Favorito     Atrás  Volver",11,0xff9fb4c8,false));renderGrid(false);
 }
 void renderNav(){nav.removeAllViews();addNav("⌕  Buscar","Buscar");addNav("▦  Todos los canales","Todos");addNav("★  Favoritos","Favoritos");TextView cap=u.text("CATEGORÍAS",10,Ui.MUTED,false);cap.setPadding(u.d(11),u.d(15),0,u.d(8));nav.addView(cap);LinkedHashSet<String> cats=new LinkedHashSet<>();for(Channel c:channels)cats.add(c.category);for(String c:cats)addNav(c,c);}
 void addNav(String label,String key){TextView b=u.button(label,()->{category=key;query="";if(!key.equals("Buscar"))Catalog.prefs(this).edit().putString("category",key).apply();search.setVisibility(key.equals("Buscar")?View.VISIBLE:View.GONE);search.setText("");renderNav();renderGrid(false);if(key.equals("Buscar")){search.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);}else{View selected=nav.findViewWithTag("nav:"+key);if(selected!=null)selected.requestFocus();}});b.setTag("nav:"+key);u.focus(b,category.equals(key));LinearLayout.LayoutParams p=u.lp(-1,30);p.bottomMargin=u.d(3);nav.addView(b,p);}
 void renderGrid(boolean restore){
  if(grid==null)return;View focused=getCurrentFocus();String tag=focused!=null&&focused.getTag() instanceof String?(String)focused.getTag():lastFocus;int sy=gridScroll.getScrollY();
  visible=Catalog.filter(this,channels,category,query);section.setText((category.equals("Todos")?"Todos los canales":category)+"  ·  "+visible.size());grid.removeAllViews();
  if(visible.isEmpty()){TextView empty=u.text(category.equals("Favoritos")?"Tus favoritos, siempre a mano.\nMantén OK sobre un canal para añadirlo.":"No encontramos canales.\nPrueba otra búsqueda o actualiza la lista.",18,Ui.MUTED,false);empty.setPadding(u.d(20),u.d(35),0,0);grid.addView(empty);return;}
  LinearLayout row=null;
  for(int i=0;i<visible.size();i++){Channel c=visible.get(i);if(i%4==0){row=u.row();row.setGravity(Gravity.TOP);LinearLayout.LayoutParams rp=u.lp(-1,119);rp.bottomMargin=u.d(9);grid.addView(row,rp);}
   LinearLayout tile=u.column();tile.setGravity(Gravity.CENTER);tile.setPadding(u.d(8),u.d(8),u.d(8),u.d(8));tile.setTag("channel:"+c.id);tile.setContentDescription(c.numberText()+" "+c.name+(Catalog.favorite(this,c)?", favorito":""));u.focus(tile,false);
   ImageView logo=new ImageView(this);u.logo(logo,c);tile.addView(logo,new LinearLayout.LayoutParams(-1,0,1));u.gap(tile,7);TextView name=u.text(c.name,12,Ui.WHITE,true);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);name.setGravity(Gravity.CENTER);tile.addView(name,u.lp(-1,22));TextView n=u.text(c.numberText()+(Catalog.favorite(this,c)?"  ★":""),10,Ui.CYAN,false);n.setGravity(Gravity.CENTER);tile.addView(n,u.lp(-1,15));
   tile.setOnClickListener(v->open(c));tile.setOnLongClickListener(v->{boolean added=Catalog.toggle(this,c);Toast.makeText(this,added?"Añadido a favoritos":"Quitado de favoritos",Toast.LENGTH_SHORT).show();lastFocus="channel:"+c.id;renderGrid(true);return true;});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(u.d(4),0,u.d(4),0);row.addView(tile,p);
  }
  int remaining=(4-visible.size()%4)%4;for(int j=0;j<remaining;j++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));
  if(restore&&!intro){View target=tag==null?null:root.findViewWithTag(tag);if(target!=null){target.requestFocus();gridScroll.post(()->gridScroll.scrollTo(0,sy));}}
 }
 void open(Channel c){lastFocus="channel:"+c.id;enteringPlayer=true;ArrayList<String> ids=new ArrayList<>();for(Channel ch:visible)ids.add(ch.id);Intent intent=new Intent(this,PlayerActivity.class).putExtra("channel",c.id).putExtra("category",category).putStringArrayListExtra("ids",ids);startActivity(intent);}
 void focusFirst(){if(grid.getChildCount()>0&&grid.getChildAt(0) instanceof LinearLayout){View v=((LinearLayout)grid.getChildAt(0)).getChildAt(0);if(v!=null)v.requestFocus();}}
 void refresh(boolean manual){if(refreshing)return;refreshing=true;status.setText("Actualizando canales…");Catalog.refresh(this,(list,fresh)->{if(isDestroyed())return;refreshing=false;channels=list;View f=getCurrentFocus();String tag=f!=null&&f.getTag() instanceof String?(String)f.getTag():"";renderNav();renderGrid(true);View n=root.findViewWithTag(tag);if(n!=null&&!intro)n.requestFocus();status.setText(fresh?channels.size()+" canales disponibles":"Mostrando tu última lista · No se pudo conectar");if(manual)Toast.makeText(this,fresh?"Canales actualizados":"Conservamos tu última lista. Inténtalo más tarde.",Toast.LENGTH_SHORT).show();});}
 void welcome(){intro=true;home.setVisibility(View.INVISIBLE);FrameLayout splash=new FrameLayout(this);splash.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff071b32,0xff020813}));root.addView(splash,new FrameLayout.LayoutParams(-1,-1));LinearLayout center=u.column();center.setGravity(Gravity.CENTER);ImageView logo=u.brand(200);center.addView(logo);u.gap(center,10);TextView title=u.text("Bienvenido a Fran TV",34,Ui.WHITE,true);title.setGravity(Gravity.CENTER);center.addView(title);u.gap(center,12);TextView subtitle=u.text("Tu televisión, tu forma de disfrutar.",18,Ui.MUTED,false);subtitle.setGravity(Gravity.CENTER);center.addView(subtitle);u.gap(center,24);View light=new View(this);light.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0x0026dff1,Ui.CYAN,0x0026dff1}));center.addView(light,u.lp(130,2));splash.addView(center,new FrameLayout.LayoutParams(-1,-1));center.setAlpha(0);center.setScaleX(.96f);center.setScaleY(.96f);center.animate().alpha(1).scaleX(1).scaleY(1).setDuration(650).start();handler.postDelayed(()->{if(isDestroyed())return;home.setVisibility(View.VISIBLE);splash.animate().alpha(0).setDuration(350).withEndAction(()->{root.removeView(splash);intro=false;focusFirst();updater.check(false);}).start();},2600);}
 @Override public void onBackPressed(){if(intro){return;}if(search.getVisibility()==View.VISIBLE){search.setVisibility(View.GONE);query="";category="Todos";renderNav();renderGrid(false);focusFirst();return;}new AlertDialog.Builder(this).setTitle("¿Salir de FranTV?").setPositiveButton("Salir",(d,w)->finish()).setNegativeButton("Seguir viendo",null).show();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);updater.close();super.onDestroy();}
}
